// ── Nhãn xếp loại dùng chung cho mọi bài kiểm tra ───────────────────────────
export const STATUS = Object.freeze({
  healthy: { key: "healthy", label: "Đạt chuẩn sức khỏe", tone: "green" },
  improve: { key: "improve", label: "Cần cải thiện", tone: "amber" },
  risk: { key: "risk", label: "Cần cải thiện – có nguy cơ sức khỏe", tone: "red" },
  completed: { key: "completed", label: "Hoàn thành bài", tone: "grey" },
});

export function statusInfo(key) {
  return STATUS[key] || STATUS.completed;
}

export const PACER_15M_ESTIMATE_NOTE = "Ước tính từ PACER 15m";
export const NO_WORLD_STANDARD_NOTE = "Chưa có chuẩn thế giới cho độ tuổi này – theo dõi tiến bộ của con qua từng lần đo.";
export const PLANK_REFERENCE_NOTE = "Tham chiếu: trẻ em Mỹ 6–15 tuổi (NHANES 2012)";
export const WORLD_BANDS = ["<20", "20-50", "50-80", ">80"];

// ── Tiện ích ────────────────────────────────────────────────────────────────
const num = (v) => {
  if (v === "" || v == null) return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
};

export function ageInMonths(birthDate, testDate) {
  if (!birthDate || !testDate) return null;
  const b = new Date(birthDate);
  const t = new Date(testDate);
  if (isNaN(b.getTime()) || isNaN(t.getTime())) return null;
  let months = (t.getFullYear() - b.getFullYear()) * 12 + (t.getMonth() - b.getMonth());
  if (t.getDate() < b.getDate()) months -= 1;
  return months < 0 ? null : months;
}

// Khối 1–5 dùng PACER 15m, khối 6 trở lên dùng 20m.
export function defaultPacerType(grade) {
  const g = Number(grade);
  return Number.isFinite(g) && g >= 6 ? "20m" : "15m";
}

export function resolvePacerType(pacerType, grade) {
  if (pacerType === "15m" || pacerType === "20m") return pacerType;
  return defaultPacerType(grade);
}

export function convertLaps15to20(laps) {
  const n = num(laps);
  if (n == null) return null;
  const map = FITNESS_NORMS.pacer15_to_20.map;
  const key = String(Math.max(1, Math.min(298, Math.round(n))));
  return map[key] ?? null;
}

// Z-score BMI-for-age theo bảng LMS của WHO 2007 (tuổi theo tháng).
export function bmiZScore(sex, ageMonths, bmi) {
  const table = sex === "female" ? FITNESS_NORMS.bmi_who2007.lms.girls : FITNESS_NORMS.bmi_who2007.lms.boys;
  const value = num(bmi);
  if (value == null || value <= 0 || ageMonths == null) return null;
  const month = Math.min(229, Math.max(60, Math.round(ageMonths)));
  const row = table[String(month)];
  if (!row) return null;
  const [L, M, S] = row;
  return (Math.pow(value / M, L) - 1) / (L * S);
}

export function nutritionLabelFromZ(z) {
  const c = FITNESS_NORMS.bmi_who2007.cutoffs_z;
  if (z == null) return "Chưa đủ dữ liệu";
  if (z < c.severe_thinness) return "Gầy còm nặng";
  if (z < c.thinness) return "Gầy còm";
  if (z <= c.overweight) return "Bình thường";
  if (z <= c.obesity) return "Thừa cân";
  return "Béo phì";
}

// Bách phân vị thế giới theo số lượt PACER 20m (nội suy tuyến tính giữa các centile).
export function pacerWorldPercentile(sex, ageYears, laps20) {
  const set = FITNESS_NORMS.pacer20_world.laps[sex === "female" ? "girls" : "boys"];
  const row = set && set[String(ageYears)];
  const laps = num(laps20);
  if (!row || laps == null || laps <= 0) return null;
  const centiles = FITNESS_NORMS.pacer20_world.centiles;
  const last = row.length - 1;
  if (laps <= row[0]) return Math.max(1, Math.round((laps / row[0]) * centiles[0]));
  if (laps >= row[last]) return Math.min(99, Math.round(centiles[last] + (laps - row[last])));
  for (let i = 0; i < last; i++) {
    if (laps >= row[i] && laps <= row[i + 1]) {
      const t = (laps - row[i]) / (row[i + 1] - row[i]);
      return Math.round(centiles[i] + t * (centiles[i + 1] - centiles[i]));
    }
  }
  return null;
}

export function worldBand(percentile) {
  if (percentile == null) return null;
  if (percentile < 20) return { band: "<20", label: "Thấp" };
  if (percentile < 50) return { band: "20-50", label: "Dưới trung bình" };
  if (percentile < 80) return { band: "50-80", label: "Trên trung bình" };
  return { band: ">80", label: "Nổi bật" };
}

function pushupMin(sexKey, ageYears) {
  const t = FITNESS_NORMS.hfz.pushup_min[sexKey];
  const k = ageYears >= 17 ? "17+" : String(Math.max(5, ageYears));
  return t[k] ?? null;
}

function sitReachMinInch(sexKey, ageYears) {
  const t = FITNESS_NORMS.hfz.sit_and_reach_min_inch[sexKey];
  const k = ageYears >= 17 ? "17+" : String(Math.max(5, ageYears));
  return t[k] ?? null;
}

function pacerHfzMinLaps(sexKey, ageYears) {
  const t = FITNESS_NORMS.hfz.pacer20_min_laps[sexKey];
  const a = Math.max(10, Math.min(18, ageYears));
  return t[String(a)] ?? null;
}

function vo2Thresholds(sexKey, ageYears) {
  const t = FITNESS_NORMS.hfz.vo2max[sexKey];
  if (ageYears == null || ageYears < 5) return null;
  return ageYears >= 18 ? t[">17"] : (t[String(ageYears)] ?? null);
}

function plankMedian(sexKey, ageYears) {
  if (ageYears == null || ageYears < 6 || ageYears > 15) return null;
  return FITNESS_NORMS.plank_us.median_seconds[sexKey][String(ageYears)] ?? null;
}

export function vo2MaxFromLaps(laps20, ageYears) {
  const laps = num(laps20);
  if (laps == null || ageYears == null) return null;
  return Math.round((45.619 + 0.353 * laps - 1.121 * ageYears) * 10) / 10;
}

// ── Đánh giá một học sinh theo toàn bộ chuẩn tham chiếu ─────────────────────
export function evaluate({ sex, birthDate, testDate, heightCm, weightKg, pacerLaps, pacerType, pushups, plankSec, sitReachCm }) {
  const sexKey = sex === "female" ? "girls" : "boys";
  const months = ageInMonths(birthDate, testDate);
  const ageYears = months == null ? null : Math.floor(months / 12);
  const out = { ageMonths: months, ageYears, bmi: null, pacer: null, pushup: null, sitReach: null, plank: null };

  // BMI — WHO 2007 (z-score)
  const h = num(heightCm);
  const w = num(weightKg);
  const bmi = h != null && w != null && h > 0 ? Math.round((w / Math.pow(h / 100, 2)) * 100) / 100 : null;
  if (bmi != null) {
    const z = months == null ? null : bmiZScore(sex, months, bmi);
    const c = FITNESS_NORMS.bmi_who2007.cutoffs_z;
    let key = "completed";
    if (z != null) {
      if (z < c.severe_thinness || z > c.obesity) key = "risk";
      else if (z < c.thinness || z > c.overweight) key = "improve";
      else key = "healthy";
    }
    const info = statusInfo(key);
    out.bmi = { value: bmi, z, nutritionLabel: nutritionLabelFromZ(z), status: info.key, statusLabel: info.label, tone: info.tone };
  }

  // PACER — quy đổi 15m → 20m, bách phân vị thế giới, HFZ theo FitnessGram
  const laps = num(pacerLaps);
  if (laps != null) {
    const type = pacerType === "15m" ? "15m" : "20m";
    const converted = type === "15m";
    const laps20 = converted ? convertLaps15to20(laps) : laps;
    const hasWorldAge = ageYears != null && ageYears >= 9 && ageYears <= 17;
    const percentile = hasWorldAge ? pacerWorldPercentile(sex, ageYears, laps20) : null;
    const bandInfo = worldBand(percentile);
    const minLaps = ageYears == null ? null : pacerHfzMinLaps(sexKey, ageYears);
    const vo2 = vo2MaxFromLaps(laps20, ageYears);
    let key = "completed";
    if (ageYears != null && ageYears >= 10 && minLaps != null) {
      if (laps20 != null && laps20 >= minLaps) {
        key = "healthy";
      } else {
        const th = vo2Thresholds(sexKey, ageYears);
        const riskMax = th ? th.NI_health_risk_max : null;
        key = riskMax != null && vo2 != null && vo2 <= riskMax ? "risk" : "improve";
      }
    }
    const info = statusInfo(key);
    out.pacer = {
      laps,
      pacerType: type,
      laps20,
      converted,
      hfzMinLaps: minLaps,
      vo2max: vo2,
      percentile,
      band: bandInfo ? bandInfo.band : null,
      worldLabel: bandInfo ? bandInfo.label : null,
      worldAvailable: percentile != null,
      status: info.key,
      statusLabel: info.label,
      tone: info.tone,
    };
  }

  // Push-up — FitnessGram HFZ
  const pu = num(pushups);
  if (pu != null) {
    const min = ageYears == null ? null : pushupMin(sexKey, ageYears);
    const info = statusInfo(min == null ? "completed" : pu >= min ? "healthy" : "improve");
    out.pushup = { value: pu, min, status: info.key, statusLabel: info.label, tone: info.tone };
  }

  // Sit & Reach — chuẩn FitnessGram tính theo inch
  const cm = num(sitReachCm);
  if (cm != null) {
    const inch = Math.round((cm / 2.54) * 10) / 10;
    const minInch = ageYears == null ? null : sitReachMinInch(sexKey, ageYears);
    const info = statusInfo(minInch == null ? "completed" : inch >= minInch ? "healthy" : "improve");
    out.sitReach = { valueCm: cm, valueInch: inch, minInch, status: info.key, statusLabel: info.label, tone: info.tone };
  }

  // Plank — chỉ có dữ liệu tham chiếu trẻ em Mỹ, không có chuẩn quốc tế
  const ps = num(plankSec);
  if (ps != null) {
    const median = ageYears == null ? null : plankMedian(sexKey, ageYears);
    const info = statusInfo("completed");
    out.plank = { value: ps, median, note: PLANK_REFERENCE_NOTE, status: info.key, statusLabel: info.label, tone: info.tone };
  }

  return out;
}